const { native } = require('./config/_import.js')
const { logDir } = require('./config/log_dir.js')
const { conOptions } = require('./config/connection_options.js')

const path = require('path')
const logfilename = __filename.split(path.sep).pop().replace('.js', '.log')
conOptions.logfile = path.join(logDir, logfilename)

let connection
try {
  // set get kill
  connection = native.createConnection(conOptions)
  const iris = connection.createIris()
  console.log(' Setting global ^test ')
  iris.set('hello world!', '^test', 1)

  console.log('^test(1): ', iris.get('^test', 1))

  // unicode
  const pop = 'Iñtërnâtiônàlizætiøn☃💩'
  iris.set(pop, '^test', 2)
  console.log('^test(2): ', iris.get('^test', 2))

  iris.kill('^test', 1)

  const isdef = iris.isDefined('^test')
  console.log('Is ^test defined: ', isdef === 0)

  console.log('Setting ^test2')
  iris.set(1, '^test2', 1)

  console.log('Locking ^test2')
  iris.lock('S', 0, '^test2', 1)

  console.log('Unlocking ^test2')
  iris.unlock('S', '^test2', 1)

  console.log('Releasing all locks')
  iris.releaseAllLocks()

  connection.close()
} catch (err) {
  console.log(err)
  if (connection) {
    connection.close()
  }
}
